<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
import { Activity, SlidersHorizontal, Cpu, CircuitBoard, ListTree, Clock3, Settings2, RefreshCw, Download, ArrowUpRight, Check, AlertCircle, Database, ChevronRight, Radio, Search, X, Menu, PlugZap, ShieldCheck, Sparkles, Info } from '@lucide/vue'
import InfoTip from './components/InfoTip.vue'
import BrandMark from './components/BrandMark.vue'
import HistoryChart from './components/HistoryChart.vue'
import AIView from './components/AIView.vue'
import AboutView from './components/AboutView.vue'
import ProcessView from './components/ProcessView.vue'
import type {Overview,Settings,Status,Sensor} from './types'
const view=ref('overview'), hours=ref(1), custom=ref(false), from=ref(''), to=ref(''), data=ref<Overview|null>(null), state=ref<Status|null>(null), settings=ref<Settings|null>(null)
const loading=ref(true), refreshing=ref(false), auth=ref(false), error=ref(''), notice=ref(''), auto=ref(true), menu=ref(false), kind=ref('power'), sensorGroup=ref('all'), search=ref(''), technical=ref(false)
const saving=ref(''), collectorDirty=ref(false), interval=ref(10), thermal=ref(30), processInterval=ref(30), processTop=ref(5), enabled=ref<string[]>([]), revision=ref(''), price=ref(''), tariffDate=ref(''), tariffDescription=ref(''), tariffDirty=ref(false)
let timer:ReturnType<typeof setInterval>|undefined, requestId=0
const format=(n:number|null|undefined,d=1)=>n===null||n===undefined?'—':n.toLocaleString('pt-BR',{maximumFractionDigits:d})
const money=(n:number|null|undefined)=>n===null||n===undefined?'—':n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const when=(n:number|undefined|null,full=false)=>n?new Intl.DateTimeFormat('pt-BR',{...(full?{day:'2-digit',month:'2-digit'}:{}),hour:'2-digit',minute:'2-digit',second:full?undefined:'2-digit',timeZone:'America/Sao_Paulo'}).format(n):'Sem leitura'
const dayInput=(ms:number)=>new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'America/Sao_Paulo'}).format(ms)
const duration=(seconds:number)=>seconds<60?`${Math.round(seconds)} s`:`${Math.floor(seconds/3600)} h ${Math.floor(seconds%3600/60)} min`
const latest=(key:string)=>data.value?.latest[key]?.value
const running=computed(()=>state.value?.state==='running')
const nav=[{id:'overview',label:'Resumo',icon:Activity},{id:'sensors',label:'Sensores',icon:CircuitBoard},{id:'processes',label:'Processos',icon:ListTree},{id:'events',label:'Eventos',icon:Clock3},{id:'ai',label:'Análises com IA',icon:Sparkles},{id:'about',label:'Sobre e privacidade',icon:Info}]
const names:Record<string,string>={system:'Sistema e utilização',powercap:'Energia da CPU',gpu:'GPU',thermal:'Temperaturas e ventoinhas',processes:'Processos (CPU e memória)'}
const events:Record<string,string>={session_started:'Coleta iniciada',session_stopped:'Coleta encerrada',unclean_session_detected:'Coleta retomada após interrupção',configuration_changed:'Configuração do coletor alterada',configuration_rejected:'Alteração de configuração recusada',storage_recovered:'Gravação recuperada',suspend_gap_detected:'Intervalo de suspensão detectado',wall_clock_changed:'Relógio do sistema alterado',collection_gap:'Intervalo sem coleta'}
const filteredSensors=computed(()=>data.value?.sensors.filter(s=>(sensorGroup.value==='all'||s.collector===sensorGroup.value)&&`${s.label} ${s.metric} ${s.scope}`.toLowerCase().includes(search.value.toLowerCase()))||[])
const currentTariff=computed(()=>settings.value?.tariffs.filter(t=>t.effective_ms<=Date.now()).at(-1))
const memoryPercent=computed(()=>{const used=latest('memory_used_bytes'),total=latest('memory_total_bytes');return used!==undefined&&total?used/total*100:0})
const filterLabel=computed(()=>custom.value?'Período personalizado':hours.value===1?'Última hora':hours.value===6?'Últimas 6 horas':hours.value===24?'Últimas 24 horas':hours.value===168?'Últimos 7 dias':'Últimos 30 dias')
function energy(kwh:number|null){if(kwh===null)return'—';return kwh<1?`${format(kwh*1000,2)} Wh`:`${format(kwh,3)} kWh`}
function go(value:string){view.value=value;menu.value=false;history.replaceState(null,'',`/?view=${value}`);document.querySelector('main')?.scrollTo(0,0)}
function params(){const query=new URLSearchParams({hours:String(hours.value)});if(custom.value&&from.value&&to.value){query.set('start_ms',String(new Date(from.value).getTime()));query.set('end_ms',String(new Date(to.value).getTime()))};return query}
async function api<T>(path:string,options:RequestInit={}):Promise<T>{const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(r.status===401){auth.value=true;throw new Error('Acesso local necessário.')};if(!r.ok){const body=await r.json().catch(()=>({}));throw new Error(typeof body.detail==='string'?body.detail:'Não foi possível concluir a operação. Verifique os campos e tente novamente.')};return r.json()}
function fillSettings(value:Settings){settings.value=value;if(!collectorDirty.value){interval.value=value.collector.values.interval_seconds;thermal.value=value.collector.values.thermal_interval_seconds;processInterval.value=value.collector.values.process_interval_seconds??30;processTop.value=value.collector.values.process_top_n??5;enabled.value=[...value.collector.values.enabled_collectors];revision.value=value.collector.revision};if(!tariffDirty.value&&!tariffDate.value)tariffDate.value=dayInput(Date.now())}
async function refresh(initial=false){const id=++requestId;refreshing.value=true;error.value='';try{const [d,s,c]=await Promise.all([api<Overview>('/api/overview?'+params()),api<Status>('/api/status'),api<Settings>('/api/settings')]);if(id!==requestId)return;data.value=d;state.value=s;fillSettings(c);auth.value=false;if(initial&&d.first_record_ms&&!currentTariff.value)tariffDate.value=dayInput(d.first_record_ms)}catch(e){if(id===requestId)error.value=(e as Error).message}finally{if(id===requestId){loading.value=false;refreshing.value=false}}}
async function saveCollector(){saving.value='collector';error.value='';notice.value='';try{const result=await api<Settings['collector']>('/api/settings/collector',{method:'PUT',body:JSON.stringify({revision:revision.value,interval_seconds:Number(interval.value),thermal_interval_seconds:Number(thermal.value),process_interval_seconds:Number(processInterval.value),process_top_n:Number(processTop.value),enabled_collectors:enabled.value})});collectorDirty.value=false;revision.value=result.revision;notice.value='Configuração salva. Aguardando confirmação do coletor.';for(let i=0;i<10;i++){await new Promise(resolve=>setTimeout(resolve,500));const s=await api<Status>('/api/status');state.value=s;if(s.configuration.applied_revision===result.revision){notice.value='Configuração aplicada pelo coletor.';break}};await refresh()}catch(e){error.value=(e as Error).message}finally{saving.value=''}}
async function saveTariff(){saving.value='tariff';error.value='';notice.value='';try{await api('/api/settings/tariffs',{method:'POST',body:JSON.stringify({price:price.value,effective_date:tariffDate.value,description:tariffDescription.value})});tariffDirty.value=false;price.value='';notice.value='Tarifa salva. Os custos respeitam a data de vigência.';await refresh()}catch(e){error.value=(e as Error).message}finally{saving.value=''}}
function reading(s:Sensor){if(s.value===null)return'Sem leitura';const val=technical.value?s.raw_value:s.value;const unit=technical.value?s.raw_unit:s.unit;if(unit==='bytes'&&val!==null)return`${format(val/1024**3,2)} GiB`;return`${format(val,unit==='percent'?1:2)} ${unit}`}
function download(){window.location.assign('/api/export.csv?'+params())}
onMounted(async()=>{const chosen=new URLSearchParams(location.search).get('view');if(['overview','sensors','processes','events','settings','ai','about'].includes(chosen||''))view.value=chosen!;const access=new URLSearchParams(location.hash.slice(1)).get('access');if(access){history.replaceState(null,'',location.pathname+location.search);try{await api('/api/session',{method:'POST',headers:{Authorization:`Bearer ${access}`}})}catch(e){error.value=(e as Error).message;loading.value=false;return}}await refresh(true);timer=setInterval(()=>{if(auto.value&&!document.hidden&&!saving.value&&!collectorDirty.value&&!tariffDirty.value)refresh()},30000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>

<template>
<a class="skip-link" href="#main">Ir para o conteúdo</a>
<div v-if="auth" class="access-screen"><div class="access-box"><ShieldCheck :size="36"/><h1>Conecte este navegador</h1><p>No terminal deste PC, execute <code>vatilume</code>. O lançador abre seu navegador padrão com o acesso privado.</p><p class="muted">Cada navegador precisa de sua própria sessão. Abrir somente o endereço não autoriza o primeiro acesso. A conexão fica disponível por até 24 horas, somente neste PC.</p><button class="button primary" @click="refresh(true)">Verificar sessão novamente</button><p v-if="error" role="alert">{{error}}</p></div></div>
<div v-else class="app-shell">
<aside :class="['sidebar',{expanded:menu}]" aria-label="Navegação principal"><a class="brand" aria-label="Vatilume, abrir resumo" href="/" @click.prevent="go('overview')"><span class="brand-symbol"><BrandMark/></span><span class="brand-name">Vatilume<span class="brand-second">Energia e sinais do PC</span></span></a><div class="workspace-label">Meu computador <span class="local-label">Local</span></div><nav><button v-for="item in nav" :key="item.id" :class="['nav-item',{selected:view===item.id}]" :aria-current="view===item.id?'page':undefined" @click="go(item.id)"><component :is="item.icon" :size="18"/>{{item.label}}</button></nav><div class="sidebar-bottom"><button :class="['nav-item',{selected:view==='settings'}]" :aria-current="view==='settings'?'page':undefined" @click="go('settings')"><Settings2 :size="18"/>Configurações</button><div class="sidebar-note"><span :class="['status-dot',running?'positive':'warning']"></span>{{running?'Coletor em execução':state?'Verificar coletor':'Conectando'}}<small>v{{settings?.version||'0.2.0'}} · somente neste PC</small></div></div></aside>
<div class="workspace"><header class="topbar"><button class="icon-button mobile-menu" aria-label="Abrir navegação" :aria-expanded="menu" @click="menu=!menu"><Menu :size="21"/></button><span class="breadcrumb">Meu computador<ChevronRight :size="14"/><strong>{{view==='settings'?'Configurações':nav.find(n=>n.id===view)?.label}}</strong></span><div class="topbar-right"><span class="updated">Última leitura {{when(data?.last_record_ms)}}</span><button class="icon-button" aria-label="Atualizar dados" :disabled="refreshing" @click="refresh()"><RefreshCw :size="17" :class="{rotating:refreshing}"/></button></div></header>
<main id="main" tabindex="-1">
<div v-if="error" role="alert" class="banner error"><AlertCircle :size="18"/><span>{{error}}</span><button class="icon-button" aria-label="Fechar aviso" @click="error='' "><X :size="16"/></button></div>
<div v-if="notice" role="status" class="banner success"><Check :size="18"/><span>{{notice}}</span><button class="icon-button" aria-label="Fechar confirmação" @click="notice='' "><X :size="16"/></button></div>
<div class="page-heading"><div><h1>{{view==='overview'?'Monitoramento do PC':view==='sensors'?'Sensores':view==='processes'?'Processos':view==='events'?'Eventos':view==='ai'?'Análises com IA':view==='about'?'Sobre o Vatilume':'Configurações'}}</h1><p>{{view==='overview'?'Energia reportada, uso e condições do hardware.':view==='sensors'?'Leituras disponíveis no período selecionado.':view==='processes'?'Atividade observada de aplicativos e seus intervalos.':view==='events'?'O que aconteceu durante a coleta.':view==='ai'?'Respostas com dados consultáveis e gasto controlado.':view==='about'?'Seu histórico, seus dados e software livre.':'Ajuste a coleta e o cálculo de custo.'}}</p></div><span v-if="view==='overview'" :class="['status-badge',running?'positive':'warning']"><span class="status-dot"></span>{{running?'Coletando':state?.state==='degraded'?'Coleta com avisos':'Sem coleta recente'}}</span></div>
<section v-if="!['settings','about'].includes(view)" class="filterbar" aria-label="Filtros do histórico"><div class="filter-period"><SlidersHorizontal :size="16"/><label for="period">Período</label><select id="period" :value="custom?'custom':hours" @change="custom=($event.target as HTMLSelectElement).value==='custom';if(!custom){hours=Number(($event.target as HTMLSelectElement).value);refresh()}"><option :value="1">Última hora</option><option :value="6">Últimas 6 horas</option><option :value="24">Últimas 24 horas</option><option :value="168">Últimos 7 dias</option><option :value="720">Últimos 30 dias</option><option value="custom">Personalizado</option></select></div><div v-if="custom" class="custom-period"><label>De<input v-model="from" type="datetime-local"></label><label>Até<input v-model="to" type="datetime-local"></label><button class="button small" :disabled="!from||!to||refreshing" @click="refresh()">Aplicar período</button></div><div class="filter-actions"><label class="auto-refresh"><input v-model="auto" type="checkbox">Atualizar automaticamente</label><button class="button small" :disabled="!data?.sample_count" @click="download"><Download :size="15"/>Exportar CSV</button></div></section>
<div v-if="loading" class="loading-state" role="status" aria-label="Carregando histórico"><div class="skeleton short"></div><div class="skeleton"></div><div class="skeleton chart-skeleton"></div><p>Consultando o histórico do coletor…</p></div>
<template v-else-if="view==='overview'">
<div v-if="!data?.sample_count" class="empty-state"><Database :size="32"/><h2>Nenhuma amostra neste período</h2><p>Experimente uma janela maior ou aguarde novas leituras do coletor.</p><button class="button" @click="hours=24;custom=false;refresh()">Ver últimas 24 horas</button></div>
<template v-else>
<section class="energy-section" aria-labelledby="energy-title"><div class="section-heading"><h2 id="energy-title">Energia no período</h2><InfoTip label="Sobre os dados de energia">São leituras reportadas de componentes, não o consumo total na tomada. CPU e GPU aparecem separadamente. Lacunas não são preenchidas com zero.</InfoTip><span class="section-meta">{{filterLabel}}</span></div><div class="energy-table"><div class="energy-head"><span>Componente</span><span>Energia reportada</span><span>Custo correspondente<InfoTip label="Como o custo é calculado">Energia do componente multiplicada pela tarifa válida em cada intervalo. Períodos sem tarifa não são cobrados. O valor não representa o custo total do gabinete.</InfoTip></span><span>Tempo coberto</span></div><div v-for="component in data.components" :key="component.id" class="energy-row"><span class="component-name"><span :class="['component-icon',component.id]"><Cpu v-if="component.id==='cpu'" :size="19"/><CircuitBoard v-else :size="19"/></span><span><strong>{{component.label}}</strong><small>{{component.id==='cpu'?'Pacote do processador':'Domínio reportado pela GPU'}}</small></span></span><span class="energy-value">{{energy(component.energy_kwh)}}</span><span><strong class="cost-value">{{component.cost_brl===null?(component.energy_kwh===null?'Sem intervalos válidos':'Sem tarifa no período'):money(component.cost_brl)}}</strong><small v-if="component.cost_brl!==null&&component.priced_seconds+1<component.covered_seconds" class="warning-text">Parte do período sem tarifa</small><button v-if="component.cost_brl===null&&component.energy_kwh!==null" class="text-button" @click="go('settings')">Configurar kWh<ArrowUpRight :size="13"/></button></span><span class="coverage-value">{{duration(component.covered_seconds)}}<small>{{format(component.coverage_percent,1)}}% da janela <InfoTip :label="`Sobre a cobertura da ${component.label}`">Tempo com intervalos válidos para calcular energia dentro da janela selecionada. Uma coleta iniciada recentemente terá cobertura menor em uma janela de 24 horas.</InfoTip></small></span></div></div><div class="section-footnote"><span class="subtle-dot"></span>Somente componentes monitorados<InfoTip label="O que está fora do valor exibido">Outros componentes e perdas da fonte ainda não são estimados. Periféricos externos ficam fora do escopo. Subdomínios da CPU não são somados ao pacote, evitando dupla contagem.</InfoTip><button class="text-button push-right" @click="go('sensors')">Examinar sensores<ChevronRight :size="14"/></button></div></section>
<div class="analysis-layout"><section class="history-section"><div class="section-heading"><h2>Histórico</h2><InfoTip label="Como ler o histórico">Médias por intervalo. A potência da CPU vem da variação do contador de energia; a GPU reporta sua própria potência. Espaços sem leituras suficientes ficam vazios.</InfoTip></div><div class="chart-toolbar"><div class="segmented" aria-label="Tipo de histórico"><button v-for="item in [{id:'power',name:'Potência'},{id:'usage',name:'Uso'},{id:'temperature',name:'Temperatura'}]" :key="item.id" :class="{active:kind===item.id}" :aria-pressed="kind===item.id" @click="kind=item.id">{{item.name}}</button></div><div class="legend"><span><i class="cpu-swatch"></i>CPU</span><span><i class="gpu-swatch"></i>GPU</span></div></div><HistoryChart :points="data.series" :kind="kind"/></section><section class="now-section"><div class="section-heading"><h2>Leituras recentes</h2><InfoTip label="Sobre as leituras recentes">Últimos valores encontrados no período selecionado. Ao selecionar um período passado, estas leituras também pertencem àquele período.</InfoTip></div><div class="reading-row"><span>Uso da CPU</span><strong>{{format(latest('cpu_percent'))}}<small>%</small></strong></div><div class="reading-row"><span>Uso da GPU</span><strong>{{format(latest('gpu_percent'))}}<small>%</small></strong></div><div class="memory-reading"><div><span>Memória RAM</span><strong>{{latest('memory_used_bytes')===undefined?'—':format(latest('memory_used_bytes')!/1024**3,1)}}<small> / {{latest('memory_total_bytes')===undefined?'—':format(latest('memory_total_bytes')!/1024**3,1)}} GiB</small></strong></div><div class="memory-track" role="meter" aria-label="Utilização de memória RAM" :aria-valuenow="Math.round(memoryPercent)" :aria-valuemin="0" :aria-valuemax="100"><span :style="{width:memoryPercent+'%'}"></span></div></div><div class="reading-row"><span>Temperatura da CPU</span><strong>{{format(latest('cpu_temp'))}}<small>°C</small></strong></div><div class="reading-row"><span>Temperatura da GPU</span><strong>{{format(latest('gpu_temp'))}}<small>°C</small></strong></div><div class="device-info"><Cpu :size="17"/><span>{{data.inventory.cpu_model||'Processador'}}<small>{{data.sensors.length}} fontes no período</small></span></div></section></div>
<section class="activity-section"><div class="section-heading"><h2>Atividade da coleta</h2><span class="section-meta">{{format(data.sample_count,0)}} ciclos no período</span><button class="text-button" @click="go('events')">Ver eventos<ChevronRight :size="14"/></button></div><div v-if="data.events.length" class="recent-events"><div v-for="event in data.events.slice(0,3)" :key="event.id" class="event-preview"><span class="event-icon"><Clock3 :size="16"/></span><span>{{events[event.type]||event.type}}</span><time>{{when(event.time_ms,true)}}</time></div></div><p v-else class="muted compact">Nenhum evento registrado nesta janela.</p></section>
</template></template>
<section v-else-if="view==='sensors'" class="sensor-section"><div class="sensor-toolbar"><label class="search-field"><Search :size="17"/><input v-model="search" placeholder="Buscar sensor" aria-label="Buscar sensor"></label><label class="select-label">Grupo<select v-model="sensorGroup"><option value="all">Todos os grupos</option><option v-for="(label,key) in Object.fromEntries(Object.entries(names).filter(([name])=>name!=='processes'))" :key="key" :value="key">{{label}}</option></select></label><label class="auto-refresh"><input v-model="technical" type="checkbox">Valores brutos</label><span class="muted push-right">{{filteredSensors.length}} fontes</span></div><div class="table-scroll"><table class="sensor-table"><thead><tr><th>Sensor</th><th>Leitura</th><th>Grupo</th><th>Última leitura</th><th>Estado</th></tr></thead><tbody><tr v-for="sensor in filteredSensors" :key="sensor.id"><td><strong>{{sensor.label}}</strong><small>{{sensor.metric}}<InfoTip :label="`Origem de ${sensor.label}`"><strong>Domínio:</strong> {{sensor.scope}}<br>Unidade original: {{sensor.raw_unit}}. O valor bruto é preservado para análise técnica.</InfoTip></small></td><td class="numeric">{{reading(sensor)}}</td><td>{{names[sensor.collector]}}</td><td>{{when(sensor.time_ms)}}</td><td><span :class="['state-text',sensor.quality==='ok'?'positive':'warning']"><span class="status-dot"></span>{{sensor.quality==='ok'?'Disponível':'Sem leitura'}}</span></td></tr></tbody></table></div><div v-if="!filteredSensors.length" class="empty-state"><Search :size="26"/><h2>Nenhum sensor encontrado</h2><p>Altere o grupo, a busca ou o período selecionado.</p></div></section>
<section v-else-if="view==='events'" class="events-section"><div v-for="event in data?.events" :key="event.id" class="event-row"><span class="event-icon"><Clock3 :size="18"/></span><div><strong>{{events[event.type]||event.type}}</strong><time>{{when(event.time_ms,true)}}</time><details><summary>Detalhes técnicos</summary><pre>{{JSON.stringify(event.details,null,2)}}</pre></details></div></div><div v-if="!data?.events.length" class="empty-state"><Check :size="28"/><h2>Nenhum evento neste período</h2><p>Inicializações, alterações e interrupções aparecem aqui.</p></div></section>
<ProcessView v-else-if="view==='processes'&&data" :history="data.processes" :window="data.window" :enabled="settings?.collector.values.enabled_collectors.includes('processes')||false" @configure="go('settings')"/>
<AboutView v-else-if="view==='about'" :version="settings?.version"/>
<AIView v-else-if="view==='ai'" :key="filterLabel+from+to" :window="data?.window"/>
<div v-else-if="view==='settings'" class="settings-layout"><section class="settings-section"><div class="section-heading"><h2>Coletor</h2><InfoTip label="Sobre as configurações do coletor">Os ajustes são persistidos separadamente da configuração de instalação e aplicados sem apagar o histórico. A coleta continua independente desta interface.</InfoTip><span :class="['status-badge',state?.configuration.applied?'positive':'warning']">{{state?.configuration.applied?'Aplicado':'Aguardando aplicação'}}</span></div><form @submit.prevent="saveCollector"><div class="field-pair"><label>Intervalo principal<span class="input-unit"><input v-model.number="interval" type="number" min="1" max="3600" step="1" required @input="collectorDirty=true"><span>segundos</span></span></label><label>Temperaturas e ventoinhas<span class="input-unit"><input v-model.number="thermal" type="number" min="1" max="3600" step="1" required @input="collectorDirty=true"><span>segundos</span></span></label></div><p class="field-hint">Intervalos maiores reduzem a resolução do histórico.<InfoTip label="Impacto do intervalo de coleta">Contadores de energia têm alcance limitado. Intervalos muito grandes podem tornar a energia da CPU ambígua; nesse caso, o cálculo não inventa um valor. A cadência térmica é limitada pelo ciclo principal.</InfoTip></p><div class="field-pair process-limit-fields"><label>Intervalo por processo<span class="input-unit"><input v-model.number="processInterval" type="number" min="5" max="3600" step="1" required @input="collectorDirty=true"><span>segundos</span></span></label><label>Maiores processos por CPU e RSS<input v-model.number="processTop" type="number" min="1" max="10" step="1" required @input="collectorDirty=true"></label></div><p class="field-hint">Padrão: 30 s e até cinco processos por ranking. Limite de 50 ms e 4.096 PIDs por varredura.<InfoTip label="Privacidade e alcance dos processos">Somente nome curto, PID/início, CPU e RSS locais. Sem argumentos, ambiente ou caminhos. CPU só é calculada após duas leituras do mesmo processo. Processos curtos e aqueles fora do ranking podem não aparecer. Os nomes e PIDs não são enviados ao modelo; a IA recebe apelidos. A cadência depende do ciclo principal.</InfoTip></p><fieldset><legend>Grupos monitorados</legend><label v-for="(label,key) in names" :key="key" class="check-row"><input v-model="enabled" :value="key" type="checkbox" @change="collectorDirty=true"><span>{{label}}</span></label></fieldset><div class="form-footer"><span class="muted">{{collectorDirty?'Há alterações não salvas':'As alterações preservam o histórico.'}}</span><button class="button primary" type="submit" :disabled="!collectorDirty||!enabled.length||saving==='collector'||!settings?.collector.reload_supported">{{saving==='collector'?'Aplicando…':'Salvar configuração'}}</button></div></form><div class="collector-details"><div><span>Último ciclo confirmado</span><strong>{{format(state?.health.last_committed_sequence,0)}}</strong></div><div><span>Gravações pendentes</span><strong>{{state?.health.pending_cycles??'—'}}</strong></div><div><span>Descartes nesta sessão</span><strong>{{state?.health.dropped_cycles??'—'}}</strong></div></div></section>
<section class="settings-section"><div class="section-heading"><h2>Tarifa de energia</h2><InfoTip label="Qual valor do kWh informar">Informe o preço efetivo por kWh da energia, esclarecendo se inclui impostos e bandeiras. Iluminação pública e cobranças fixas não devem ser atribuídas automaticamente ao PC. Referências tarifárias dinâmicas ainda não estão integradas.</InfoTip></div><div class="tariff-current"><span>Tarifa em vigor</span><strong>{{currentTariff?`${currentTariff.price.replace('.',',')} R$/kWh`:'Não configurada'}}</strong><small>Valor informado por você · R$/kWh</small></div><form @submit.prevent="saveTariff"><div class="field-pair"><label>Valor do kWh<span class="input-unit"><input v-model="price" type="text" inputmode="decimal" placeholder="Ex.: 1,05" maxlength="20" required @input="tariffDirty=true"><span>R$/kWh</span></span></label><label>Aplicar a partir de<input v-model="tariffDate" type="date" required @input="tariffDirty=true"></label></div><label>Descrição ou origem <span class="optional">opcional</span><input v-model="tariffDescription" placeholder="Ex.: valor efetivo da conta de outubro" maxlength="180" @input="tariffDirty=true"></label><p class="field-hint">Uma nova vigência mantém as tarifas anteriores.<InfoTip label="Sobre correções de tarifas">Salvar com a mesma data corrige o valor daquela vigência. A alteração fica registrada e os custos são recalculados; as leituras do coletor permanecem intactas.</InfoTip></p><div class="form-footer"><span class="muted">{{tariffDirty?'Há alterações não salvas':'Custos ausentes não aparecem como zero.'}}</span><button class="button primary" type="submit" :disabled="!price||saving==='tariff'">{{saving==='tariff'?'Salvando…':'Salvar tarifa'}}</button></div></form><div v-if="settings?.tariffs.length" class="tariff-history"><h3>Histórico de vigências</h3><div v-for="tariff in [...settings.tariffs].reverse()" :key="tariff.id"><span>{{dayInput(tariff.effective_ms).split('-').reverse().join('/')}}<small>{{tariff.description||'Valor informado manualmente'}}</small></span><strong>{{tariff.price.replace('.',',')}} R$/kWh</strong></div></div></section></div>
<footer class="page-footer"><span><ShieldCheck :size="14"/>Coleta local · IA sob demanda</span><span>Horário de Brasília</span></footer>
</main></div></div>
</template>
